"""각 영상의 적용 장면. UI·실행 로그가 아닌 교육용 설계 예시."""
FLOW = {}
def add(key, text):
    rows=[r.split('||') for r in text.strip().splitlines() if r.strip()]
    assert all(len(r)==6 for r in rows), (key,[len(r) for r in rows])
    FLOW[key]=[dict(zip(('title','input','action','check','failure','repair'),r)) for r in rows]

